import re
import os
import json

# Patterns for real sensitive credentials
patterns = {
    'aws_access_key': r'AKIA[A-Z0-9]{16}',
    'aws_secret_key': r'[A-Za-z0-9/+=]{40}(?=\s|"|\]|,|$)',
    'github_token': r'ghp_[A-Za-z0-9_]{36,}',
    'huggingface_token': r'hf_[A-Za-z0-9_]{20,}',
}

# Files to scan (exclude node_modules, .git, and large data dirs)
exclude_dirs = {'.git', '__pycache__', 'node_modules', '.venv', 'venv'}

found_secrets = {}

for root, dirs, files in os.walk('/app/dclm'):
    dirs[:] = [d for d in dirs if d not in exclude_dirs]

    for file in files:
        if file.startswith('.'):
            continue
        filepath = os.path.join(root, file)

        # Skip binary files and very large files
        try:
            size = os.path.getsize(filepath)
            if size > 10*1024*1024:  # Skip files > 10MB
                continue
        except:
            continue

        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                for pattern_name, pattern in patterns.items():
                    matches = re.findall(pattern, content)
                    if matches:
                        for match in matches:
                            key = f"{filepath}:{pattern_name}"
                            if key not in found_secrets:
                                found_secrets[key] = set()
                            found_secrets[key].add(match)
        except:
            pass

for key, values in sorted(found_secrets.items()):
    filepath, pattern_name = key.rsplit(':', 1)
    print(f"{filepath} ({pattern_name}): {values}")
EOF

